// content fingerprint for the resource
function etagOf(body) { return '"' + body.length.toString(16) + '-' + (body.split('').reduce((h,c)=>((h*31)+c.charCodeAt(0))>>>0,7)).toString(16) + '"'; }
function stripWeak(tag) { return tag.replace(/^W\//, ''); }
let resource = { body: 'config-v1' };
function handle(req) {
  const current = etagOf(resource.body);
  const inm = req.headers['If-None-Match'];
  if (inm && stripWeak(inm) === stripWeak(current)) {
    return { status: 304, etag: current, body: '' };
  }
  return { status: 200, etag: current, body: resource.body };
}
const out = [];
// 1. cold fetch, no validator -> 200, learn the ETag
let r1 = handle({ headers: {} });
out.push(r1.status);
const stored = r1.etag;
// 2. revalidate with stored ETag, content unchanged -> 304
let r2 = handle({ headers: { 'If-None-Match': stored } });
out.push(r2.status);
// 3. content changes on the origin, same validator no longer matches -> 200
resource.body = 'config-v2';
let r3 = handle({ headers: { 'If-None-Match': stored } });
out.push(r3.status);
console.log(out.join(' '));
